                       ,[DestinationEquipmentType] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DestinationEquipmentType'), @sync_supported_columns_tblTransactionLineItems)) WHEN 0 THEN existingData.[DestinationEquipmentType] ELSE remoteChanges.[DestinationEquipmentType] END
                       ,[DestinationEquipmentModel] = CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('DestinationEquipmentModel'), @sync_supported_columns_tblTransactionLineItems)) WHEN 0 THEN existingData.[DestinationEquipmentModel] ELSE remoteChanges.[DestinationEquipmentModel] END
