nc_supported_columns_tblTransactionLineItems)) WHEN 0 THEN NULL ELSE @TemperatureQualityStatus END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MeterStartObtainedAutomaticallyFlag'), @sync_supported_columns_tblTransactionLineItems)) WHEN 0 THEN NULL ELSE @MeterStartObtainedAutomaticallyFlag END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('MeterStopObtainedAutomaticallyFlag'), @sync_supported_columns_tblTransactionLineItems)) WHEN 0 THEN NULL ELSE @MeterStopObtainedAutomaticallyFlag END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('NetVolumeIndicator'), @sync_supported_columns_tblTransactionLineItems)) WHEN 0 THEN NULL ELSE @NetVolumeIndicator END))
